1	import { useQuery } from '@tanstack/react-query';
2	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
3	import type { ContentfulClientApi } from 'contentful';
4	import { useContentfulClient } from './useContentfulClient';
5	import { filterByRegion, pickMostSpecificByRegion } from '../utils/resolveByRegion';
6	import { CONTENT_TYPE_IDS } from '../config/contentfulMapping';
7	import { CONTENTFUL_FALLBACK_LOCALE } from '../config/contentful';
8	import type { HeaderNavigationEntry, HeaderNavItemEntry } from '../types/contentful';
9	
10	// Contentful resolves nested references `include` levels deep, and the header nav model is
11	// one level deeper than the footer's: headerNavigation → items (1) → columns (2) → links (3)
12	// → link.regions (4). See footer/index.tsx's FOOTER_INCLUDE_DEPTH comment for what getting
13	// this wrong looks like (an under-resolved `regions` reference arrives as an unresolvable
14	// link stub with no `fields`, which throws when read).
15	const HEADER_NAV_INCLUDE_DEPTH = 4;
16	
17	const HEADER_NAV_QUERY_KEY = 'headerNavigation';
18	
19	type UseHeaderNavResult = {
20	  /** Region-resolved header nav items for the current storefront. `undefined` only while the
21	   *  fetch is in flight — once settled (success, error, or no entry for this region) this is
22	   *  always an array, empty if there's nothing to show, so a consumer's loading indicator
23	   *  doesn't spin forever waiting for a value that will never arrive. */
24	  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
25	  isLoading: boolean;
26	  isError: boolean;
27	};
28	
29	// useMultiSite ships untyped from the base SFCC package — same cast FooterContainer already
30	// uses for this exact lookup.
31	type MultiSiteResult = { site: { id: string }; locale?: { id: string } };
32	
33	/**
34	 * Fetches the `headerNavigation` root entry from Contentful and resolves the region-scoped
35	 * entry for the current storefront, mirroring how `FooterContainer`
36	 * (overrides/app/components/footer/index.tsx) resolves `footerConfig` — same
37	 * `pickMostSpecificByRegion` root-resolution step, plus a `filterByRegion` pass over the
38	 * resolved entry's `items` array so each item's own `regions` field (per-item market
39	 * scoping, see headerNavItem.js) actually has an effect.
40	 *
41	 * Uses `@tanstack/react-query`'s `useQuery` rather than the footer's raw `useEffect`/
42	 * `useState` — the app already mounts a `QueryClientProvider` for every page via
43	 * `withReactQuery(AppConfig, ...)` in `_app-config`, so this needs no provider of its own.
44	 *
45	 * @returns the current storefront's resolved header nav items, plus query status flags.
46	 *   `items` is `undefined` while loading, on fetch failure, or when no entry resolves for
47	 *   this region — callers should treat that the same as "nothing to render yet," matching
48	 *   FooterContainer's "renders nothing" behaviour on an unresolved fetch.
49	 */
50	export const useHeaderNav = (): UseHeaderNavResult => {
51	  const { site, locale: siteLocale } = useMultiSite() as MultiSiteResult;
52	  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
53	  const { client } = useContentfulClient();
54	
55	  const { data, isLoading, isError } = useQuery({
56	    queryKey: [HEADER_NAV_QUERY_KEY, site.id, locale],
57	    queryFn: async () => {
58	      // Guaranteed non-null: `enabled: !!client` below means this only runs once a client
59	      // exists, but TypeScript can't see that gate from inside the closure.
60	      // `useContentfulClient` types the client as `ContentfulClientApi<any>` for the
61	      // Experiences SDK's benefit — with `any` chain modifiers, `EntriesQueries`'s
62	      // `locale` field resolves out of the type entirely (see its `WITH_ALL_LOCALES`
63	      // conditional), so narrow back to the real default (`undefined`) modifiers here.
64	      const entries = await (client as ContentfulClientApi<undefined>)!.getEntries({
65	        content_type: CONTENT_TYPE_IDS.headerNavigation,
66	        include: HEADER_NAV_INCLUDE_DEPTH,
67	        locale,
68	      });
69	      // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
70	      // HeaderNavigationEntry mirrors the exact nested-resolved shape `include: 4`
71	      // produces for this content model.
72	      return entries.items as unknown as HeaderNavigationEntry[];
73	    },
74	    enabled: !!client,
75	  });
76	
77	  const resolved = data ? pickMostSpecificByRegion<HeaderNavigationEntry>(data, site.id) : undefined;
78	  const items = isLoading
79	    ? undefined
80	    : resolved
81	    ? filterByRegion<HeaderNavItemEntry>(resolved.fields.items, site.id)
82	    : [];
83	
84	  return { items, isLoading, isError };
85	};
86

1	import { useCallback, useReducer } from 'react';
2	
3	/**
4	 * Phases the desktop/tablet mega-menu panel moves through:
5	 *
6	 *   closed     -> expanding   (HOVER onto a trigger while nothing is open)
7	 *   expanding  -> contentIn   (panel height reveal finished — see onExpandComplete)
8	 *   contentIn  -> open        (content fade-in finished — see onContentInComplete)
9	 *   open       -> contentOut  (HOVER onto a *different* trigger, or CLOSE)
10	 *   contentOut -> contentIn   (switching: fade-out finished, pendingItemId swapped in — no
11	 *                              height change)
12	 *   contentOut -> collapsing  (closing: fade-out finished, no pendingItemId)
13	 *   collapsing -> closed      (panel height collapse finished — see onCollapseComplete)
14	 */
15	export type MegaMenuMotionPhase = 'closed' | 'expanding' | 'contentIn' | 'open' | 'contentOut' | 'collapsing';
16	
17	export type MegaMenuMotionState = {
18	  /** The item id whose panel is mounted/positioned (Chakra Popover's own isOpen) — null only
19	   *  when phase is 'closed'. Stays the *old* item throughout a switch's contentOut phase, so
20	   *  its content can visibly fade out before pendingItemId takes over. */
21	  activeItemId: string | null;
22	  phase: MegaMenuMotionPhase;
23	  /** Set only during a switch's contentOut phase — the item that becomes active once the
24	   *  fade-out completes. Distinguishes "fading out to switch" from "fading out to close". */
25	  pendingItemId: string | null;
26	};
27	
28	type Action =
29	  | { type: 'HOVER'; id: string }
30	  | { type: 'CLOSE' }
31	  | { type: 'EXPAND_COMPLETE' }
32	  | { type: 'CONTENT_IN_COMPLETE' }
33	  | { type: 'CONTENT_OUT_COMPLETE' }
34	  | { type: 'COLLAPSE_COMPLETE' };
35	
36	const INITIAL_STATE: MegaMenuMotionState = { activeItemId: null, phase: 'closed', pendingItemId: null };
37	
38	const reducer = (state: MegaMenuMotionState, action: Action): MegaMenuMotionState => {
39	  switch (action.type) {
40	    case 'HOVER': {
41	      // Nothing open, or the previous item is still mid-collapse (rapid close-then-rehover) —
42	      // no locked height already showing, so this is a fresh open, not a switch.
43	      if (state.activeItemId === null || state.phase === 'collapsing') {
44	        return { activeItemId: action.id, phase: 'expanding', pendingItemId: null };
45	      }
46	      // Re-hovering the item already open/opening (not mid-close) — no-op.
47	      if (state.activeItemId === action.id && state.phase !== 'contentOut') {
48	        return state;
49	      }
50	      // A different item while the current one is still mid-expand: content is already hidden
51	      // (isContentVisible is false for 'expanding'), so routing through 'contentOut' would
52	      // target the same opacity value it's already at — no transition fires, no transitionend,
53	      // and onContentOutComplete never gets called to move the phase machine off 'contentOut'.
54	      // Just retarget which item is expanding instead; the height reveal continues uninterrupted.
55	      if (state.phase === 'expanding') {
56	        return { activeItemId: action.id, phase: 'expanding', pendingItemId: null };
57	      }
58	      // A different item — fade the current content out; height never moves for a switch.
59	      return { ...state, phase: 'contentOut', pendingItemId: action.id };
60	    }
61	    case 'CLOSE': {
62	      if (state.activeItemId === null || state.phase === 'collapsing') return state;
63	      // Same stuck-transition risk as HOVER above: content isn't visible yet during 'expanding',
64	      // so go straight to collapsing instead of a contentOut fade nothing can observe finishing.
65	      if (state.phase === 'expanding') {
66	        return { ...state, phase: 'collapsing', pendingItemId: null };
67	      }
68	      if (state.phase === 'contentOut' && state.pendingItemId === null) return state; // already closing
69	      return { ...state, phase: 'contentOut', pendingItemId: null };
70	    }
71	    case 'EXPAND_COMPLETE':
72	      return state.phase === 'expanding' ? { ...state, phase: 'contentIn' } : state;
73	    case 'CONTENT_IN_COMPLETE':
74	      return state.phase === 'contentIn' ? { ...state, phase: 'open' } : state;
75	    case 'CONTENT_OUT_COMPLETE': {
76	      if (state.phase !== 'contentOut') return state;
77	      return state.pendingItemId
78	        ? { activeItemId: state.pendingItemId, phase: 'contentIn', pendingItemId: null }
79	        : { ...state, phase: 'collapsing' };
80	    }
81	    case 'COLLAPSE_COMPLETE':
82	      return state.phase === 'collapsing' ? INITIAL_STATE : state;
83	    default:
84	      return state;
85	  }
86	};
87	
88	export type MegaMenuMotionControls = MegaMenuMotionState & {
89	  /** Call when the shopper hovers an L1 trigger — opens it (nothing open yet) or switches to
90	   *  it (something else already open). */
91	  hover: (id: string) => void;
92	  /** Call when the shopper closes the mega menu (Close control, Escape). */
93	  close: () => void;
94	  onExpandComplete: () => void;
95	  onContentInComplete: () => void;
96	  onContentOutComplete: () => void;
97	  onCollapseComplete: () => void;
98	};
99	
100	/**
101	 * Drives the desktop/tablet mega-menu's open/switch/close choreography as an explicit phase
102	 * state machine: first open reveals height top-to-bottom then fades content in; switching
103	 * between L1 items fades the old content out then the new content in with no height change;
104	 * closing fades content out then collapses height in reverse. Chakra's Popover only exposes a
105	 * single built-in fade/scale transition, which can't express this staged sequencing — this hook
106	 * plus list-menu-popover.tsx's CSS-driven reveal/fade replace it, while Popover itself still
107	 * handles positioning/focus-trap/Escape/a11y.
108	 *
109	 * Desktop/tablet only — the mobile drawer (`drawer-menu/`) has no motion spec yet.
110	 */
111	export const useMegaMenuMotion = (): MegaMenuMotionControls => {
112	  const [state, dispatch] = useReducer(reducer, INITIAL_STATE);
113	
114	  return {
115	    ...state,
116	    hover: useCallback((id: string) => dispatch({ type: 'HOVER', id }), []),
117	    close: useCallback(() => dispatch({ type: 'CLOSE' }), []),
118	    onExpandComplete: useCallback(() => dispatch({ type: 'EXPAND_COMPLETE' }), []),
119	    onContentInComplete: useCallback(() => dispatch({ type: 'CONTENT_IN_COMPLETE' }), []),
120	    onContentOutComplete: useCallback(() => dispatch({ type: 'CONTENT_OUT_COMPLETE' }), []),
121	    onCollapseComplete: useCallback(() => dispatch({ type: 'COLLAPSE_COMPLETE' }), []),
122	  };
123	};
