1	import React, { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
2	import { ListMenuContent } from '@salesforce/retail-react-app/app/components/list-menu/list-menu-content';
3	import {
4	  Box,
5	  Popover,
6	  PopoverContent,
7	  PopoverBody,
8	  useTheme,
9	} from '@salesforce/retail-react-app/app/components/shared/ui';
10	import { ListMenuTrigger } from './list-menu-trigger';
11	import { useUiCopy } from 'app/hooks/useUiCopy';
12	import type { MegaMenuMotionPhase } from 'app/hooks/useMegaMenuMotion';
13	import type { HeaderNavItemEntry } from 'app/types/contentful';
14	import type { HeaderNavTriggerElement } from 'app/hooks/useHeaderNavKeyboard';
15	
16	// Any real, visible focusable content a mega-menu panel can contain (leaf links; a bare
17	// <button> never occurs there today, included for robustness) — see focusFirstPanelLink below.
18	const PANEL_FOCUSABLE_SELECTOR = 'a[href], button:not([disabled])';
19	
20	// Height reveal targets 'expanding'/'collapsing' only — a switch between items must never move
21	// the height, so its 'contentIn' target snaps to 1fr with no transition instead of re-running
22	// the reveal. See useMegaMenuMotion.ts for the full phase state machine.
23	const isPanelExpanded = (phase: MegaMenuMotionPhase) => phase !== 'closed' && phase !== 'collapsing';
24	const isPanelHeightAnimating = (phase: MegaMenuMotionPhase) => phase === 'expanding' || phase === 'collapsing';
25	const isContentVisible = (phase: MegaMenuMotionPhase) => phase === 'contentIn' || phase === 'open';
26	
27	/**
28	 * Enabling a CSS `transition` and changing the property it targets in the same React commit
29	 * gives the browser no prior painted frame to interpolate from — it snaps straight to the
30	 * target with zero animation and no `transitionend`, which stalls useMegaMenuMotion's phase
31	 * machine forever waiting on a completion event that never comes (confirmed empirically:
32	 * grid-template-rows reached its final value within 50ms with no interpolation).
33	 *
34	 * Fix: defer the value change by two `requestAnimationFrame`s whenever it should animate (one
35	 * rAF isn't reliably enough to cross a real paint boundary), so the transition is already
36	 * active on a genuine prior frame before the target changes. Applies instantly otherwise.
37	 */
38	const useTransitionSafeValue = <TValue,>(target: TValue, shouldAnimate: boolean, initial: TValue): TValue => {
39	  const [value, setValue] = useState(initial);
40	
41	  useLayoutEffect(() => {
42	    if (!shouldAnimate) {
43	      setValue(target);
44	      return undefined;
45	    }
46	    let secondFrame = 0;
47	    const firstFrame = requestAnimationFrame(() => {
48	      secondFrame = requestAnimationFrame(() => setValue(target));
49	    });
50	    return () => {
51	      cancelAnimationFrame(firstFrame);
52	      if (secondFrame) cancelAnimationFrame(secondFrame);
53	    };
54	  }, [target, shouldAnimate]);
55	
56	  return value;
57	};
58	
59	type ListMenuPopoverProps = {
60	  contentComponent?: React.ElementType;
61	  item?: HeaderNavItemEntry;
62	  name?: string;
63	  itemsKey?: string;
64	  maxColumns?: number;
65	  /**
66	   * Controlled by ListMenuView (a single source of truth shared across every sibling
67	   * ListMenuPopover) rather than each instance owning its own useDisclosure() — necessary for
68	   * mutual exclusion, since this override's `closeOnBlur={false}` means nothing else closes an
69	   * already-open item.
70	   *
71	   * True for *both* the outgoing item and the incoming one during a switch, not just the
72	   * active one — see `isActiveItem` below for why.
73	   */
74	  isOpen: boolean;
75	  onOpen: () => void;
76	  onClose: () => void;
77	  /**
78	   * Whether THIS item is the one useMegaMenuMotion considers *active* (not merely pending) —
79	   * distinct from `isOpen` above. During a switch, the pending (incoming) item is `isOpen` but
80	   * not yet `isActiveItem`: its Popover mounts/positions early, while the outgoing item's
81	   * content still covers the page, so there's no positioning left to do once it actually takes
82	   * over — without this, a real flash-of-page-content gap appeared between the outgoing
83	   * Popover closing and the incoming one finishing its own first-open positioning. The pending
84	   * item's own CSS phase stays 'closed' throughout — only its Popover mount state moves early.
85	   */
86	  isActiveItem?: boolean;
87	  /**
88	   * Whether THIS item's L1 trigger should show as active/underlined — the most recently
89	   * *hovered* item, which changes instantly. Distinct from `isOpen`/`isActiveItem` above (which
90	   * stay true for the outgoing item throughout a switch's fade-out) so both triggers' underlines
91	   * animate concurrently instead of the outgoing one waiting for the switch to finish.
92	   */
93	  isTriggerActive?: boolean;
94	  /** The shared mega-menu motion phase — only meaningful for the instance where `isActiveItem`
95	   *  is true (see `phase` below). */
96	  motionPhase?: MegaMenuMotionPhase;
97	  onExpandComplete?: () => void;
98	  onContentInComplete?: () => void;
99	  onContentOutComplete?: () => void;
100	  onCollapseComplete?: () => void;
101	  /** Merged onto the trigger's real DOM node — see useHeaderNavKeyboard.ts. */
102	  triggerRef?: React.Ref<HeaderNavTriggerElement>;
103	  /** Left/Right/Home/End roving focus across L1 triggers — see useHeaderNavKeyboard.ts. */
104	  onTriggerKeyDown?: (event: React.KeyboardEvent) => void;
105	};
106	
107	// Override of base list-menu-popover.jsx: content is always rendered (Chakra's Popover hides
108	// closed content on its own — an a11y improvement over gating with `{isOpen && ...}`).
109	// closeOnBlur={false} + no onMouseLeave: the menu only closes via the Close control, a leaf
110	// link, or Escape. Imports our own list-menu-trigger.tsx override instead of base.
111	const ListMenuPopover = ({
112	  contentComponent,
113	  item,
114	  name,
115	  itemsKey,
116	  maxColumns,
117	  isOpen,
118	  onOpen,
119	  onClose,
120	  isActiveItem,
121	  isTriggerActive,
122	  motionPhase,
123	  onExpandComplete,
124	  onContentInComplete,
125	  onContentOutComplete,
126	  onCollapseComplete,
127	  triggerRef,
128	  onTriggerKeyDown,
129	}: ListMenuPopoverProps) => {
130	  const initialFocusRef = useRef<HTMLElement>(null);
131	  const ContentComponent = contentComponent || ListMenuContent;
132	  const theme = useTheme() as { components: Record<string, { baseStyle: Record<string, Record<string, unknown>> }> };
133	  const { baseStyle } = theme.components.ListMenu;
134	  const { t } = useUiCopy();
135	
136	  // A pending (isOpen yet not-yet-active) instance must stay at the 'closed' resting state —
137	  // every completion callback below is guarded by an exact phase match, so a spurious
138	  // transitionend on a non-active instance can never fire one of them.
139	  const phase: MegaMenuMotionPhase = isActiveItem ? motionPhase ?? 'closed' : 'closed';
140	  const gridTemplateRowsTarget = isPanelExpanded(phase) ? '1fr' : '0fr';
141	  const gridTemplateRows = useTransitionSafeValue(gridTemplateRowsTarget, isPanelHeightAnimating(phase), '0fr');
142	
143	  // Per the W3C WAI-ARIA APG's Disclosure Navigation Menu pattern (the canonical reference for
144	  // this exact "top-level link that also opens a dropdown" shape — confirmed against
145	  // https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/examples/disclosure-navigation/'s own
146	  // keyboard-support table): opening the menu leaves focus on the trigger — it does NOT jump
147	  // into the panel — and Down Arrow (list-menu-trigger.tsx's onEnterPanel) is the documented
148	  // fast-path a keyboard user takes from there into the panel's first link. Tab still flows
149	  // through the open panel's own links afterwards, same as any other revealed content in normal
150	  // document order — nothing here needs to intercept Tab. `autoFocus={false}` below exists only
151	  // to stop Chakra's own default (which would otherwise move focus into the panel the instant
152	  // isOpen flips true, for every open method including a mouse hover) from fighting this.
153	  const focusFirstPanelLink = () => {
154	    initialFocusRef.current?.querySelector<HTMLElement>(PANEL_FOCUSABLE_SELECTOR)?.focus();
155	  };
156	
157	  // Down Arrow can be pressed the instant the panel opens, before its reveal/fade animation has
158	  // actually finished (confirmed live against a real browser: fast keyboard input landed focus
159	  // on a link that was still 0-height/opacity-0 — the same WCAG 2.4.7 bug the old auto-focus-on-
160	  // open behaviour had, just reachable through this new path instead). If the panel is already
161	  // fully open, focus moves immediately; otherwise the request is remembered and fulfilled once
162	  // phase actually reaches 'open', not merely 'contentIn' (opacity is still ramping up then —
163	  // see isContentVisible's own comment; only 'open' means the transition has genuinely settled).
164	  const pendingEnterPanelRef = useRef(false);
165	  const onEnterPanel = () => {
