207	        <Fragment>
208	          <ListMenuTrigger
209	            item={item}
210	            name={name}
211	            isActive={isTriggerActive}
212	            onOpen={onOpen}
213	            onClose={onClose}
214	            // Only wired while actually open — ArrowDown on the trigger is a no-op while closed
215	            // (Space/Enter/click remain the only way to open it). Gating here, not just inside
216	            // onEnterPanel itself, matters: without it, an ArrowDown press on a closed trigger
217	            // could arm the pending-focus flag above and then fire later if the menu happens to
218	            // open via some other means (e.g. a hover) — this way it's a true no-op instead.
219	            onEnterPanel={isOpen ? onEnterPanel : undefined}
220	            triggerRef={triggerRef}
221	            onTriggerKeyDown={onTriggerKeyDown}
222	          />
223	          {/* Focus-return-on-close (Chakra's own useFocusOnHide, trigger="click" default) needs
224	              this same ref — Popover clones it onto ListMenuTrigger's element internally via
225	              PopoverTrigger, so no separate wiring is needed here for that half. */}
