113	/**
114	 * Header shell — fetches commerce data and distributes it as props to LeftBar and RightBar.
115	 * Renders a two-row layout: topBar row (nav + icons) + logoBar row.
116	 *
117	 * Layout sub-components:
118	 *   - LeftBar (leftBar/index.tsx): hamburger on mobile, desktop nav at tablet+
119	 *   - RightBar (rightBar/index.tsx): search + icon buttons on desktop, search/bag on mobile
120	 *
121	 * To customize styles:
122	 *   - Shell layout (topBar, logoBar): header/header.css.ts
123	 *   - Left nav group: header/leftBar/leftBar.css.ts (ZimmHeaderLeftBar)
124	 *   - Right section:  header/rightBar/rightBar.css.ts (ZimmHeaderRightBar)
125	 *
126	 * @param props see HeaderProps
127	 */
128	const Header = ({
129	  children,
130	  onMenuClick = noop,
131	  onMyAccountClick = noop,
132	  onLogoClick = noop,
133	  onMyCartClick = noop,
134	  onWishlistClick = noop,
135	  onStoreLocatorClick = noop,
136	  onAgentClick = noop,
137	  searchInputRef,
138	  ...props
139	}: HeaderProps) => {
140	  const { t } = useUiCopy();
141	  const {
142	    derivedData: { totalItems },
143	    data: basket,
144	  } = useCurrentBasket();
145	  const { isRegistered } = useCustomerType();
146	  const logout = useAuthHelper(AuthHelpers.Logout);
147	  const navigate = useNavigation();
148	  const appConfig = getConfig().app;
149	  const storeLocatorEnabled = (appConfig?.storeLocatorEnabled as boolean | undefined) ?? STORE_LOCATOR_IS_ENABLED;
150	  const commerceAgentConfig = getCommerceAgentConfig();
151	  const showLaunchAgentButton = commerceAgentConfig?.enableAgentFromHeader === 'true';
152	  const [showLoading, setShowLoading] = useState(false);
153	  const { oneClickCheckout = {} } = appConfig as { oneClickCheckout?: OneClickCheckoutConfig };
154	  const isOneClickCheckoutEnabled = oneClickCheckout.enabled;
155	
156	  // Desktop/tablet mega-menu open state (SFCC-96) — drives RightBar's 'fullSwap' Close-control
157	  // swap. `reportOpen` hands us the popover's real `onClose`, so `closeMegaMenu` can actually
158	  // close it (not just flip this mirror state). Menu stays open until Close is clicked, a leaf
159	  // link is followed, or Escape — no close-on-hover-out/outside-click.
160	  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
161	  const megaMenuCloseRef = useRef<(() => void) | null>(null);
162	  const reportMegaMenuOpen = useCallback((onClose: () => void) => {
163	    megaMenuCloseRef.current = onClose;
164	    setIsMegaMenuOpen(true);
165	  }, []);
166	  const reportMegaMenuClosed = useCallback(() => {
167	    megaMenuCloseRef.current = null;
168	    setIsMegaMenuOpen(false);
169	  }, []);
170	  const closeMegaMenu = useCallback(() => {
171	    megaMenuCloseRef.current?.();
172	  }, []);
173	  const megaMenuOpenReporter = useMemo(
174	    () => ({ reportOpen: reportMegaMenuOpen, reportClose: reportMegaMenuClosed }),
175	    [reportMegaMenuOpen, reportMegaMenuClosed],
176	  );
177	
178	  // Mobile L1/L2 drawer state (SFCC-97). Base `_app`'s `useDisclosure` passes `onMenuClick`
179	  // (its `onOpen`) to Header directly, but `isOpen`/`onClose` go straight to the sibling
180	  // `<DrawerMenu>` it renders as Header's own `children` — Header has no `onClose` prop of
181	  // its own. `useHeaderMenuExpandedState` owns the depth (closed/L1/L2) state this shell needs
182	  // for LeftBar/RightBar's `menuExpanded`, and `DrawerMenuStateContext` (provided around
183	  // `children` below) is how the nested DrawerMenu and this shell share it without Header
184	  // needing to know `_app.jsx`'s exact children shape — see both hooks' own JSDoc.
185	  const {
186	    menuExpanded: mobileMenuExpanded,
187	    handleMenuClick,
188	    handleBack,
189	    handleClose,
190	    contextValue,
191	  } = useHeaderMenuExpandedState(onMenuClick);
192	
193	  // Combined menuExpanded for LeftBar/RightBar (see headerTypes.ts): the desktop/tablet
194	  // mega-menu ('fullSwap') and the mobile drawer ('mobileL1'/'mobileL2') are mutually
195	  // exclusive by breakpoint in practice (LeftBar/RightBar's own recipes hide one control set
196	  // per breakpoint), but both pieces of state genuinely coexist in this shell — SFCC-96 owns
197	  // `isMegaMenuOpen`, SFCC-97 owns `mobileMenuExpanded`. Mobile state takes precedence when
198	  // active; otherwise fall through to the desktop mega-menu state. `onCloseMenu` below picks
199	  // the matching close handler the same way, so RightBar's single `onClose` prop always closes
200	  // whichever one is actually open.
201	  const menuExpanded: MenuExpandedState =
202	    mobileMenuExpanded !== 'closed' ? mobileMenuExpanded : isMegaMenuOpen ? 'fullSwap' : 'closed';
203	  const onCloseMenu = mobileMenuExpanded !== 'closed' ? handleClose : closeMegaMenu;
204	
205	  // Filter navigation links based on 1CC configuration
206	  const filteredNavLinks = isOneClickCheckoutEnabled
207	    ? (navLinks as NavLink[])
208	    : (navLinks as NavLink[]).filter((link) => link.name !== 'payments');
209	
210	  const onSignout = async () => {
211	    if (showLoading) return;
212	    setShowLoading(true);
213	    try {
214	      await logout.mutateAsync();
215	      navigate('/login');
216	    } finally {
217	      setShowLoading(false);
218	    }
219	  };
220	
221	  const styles = useMultiStyleConfig('Header');
222	
223	  return (
224	    <MegaMenuOpenContext.Provider value={megaMenuOpenReporter}>
225	      <chakra.header __css={styles.container} role="banner" {...props}>
226	        <chakra.div __css={HEADER_CONTENT_SX}>
227	          {showLoading && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
228	
229	          {/* ── Row 1: top bar ─────────────────────────────────────────────── */}
230	          <chakra.div __css={styles.topBar}>
231	            <LeftBar onMenuClick={handleMenuClick} menuExpanded={menuExpanded} onBack={handleBack}>
232	              <DrawerMenuStateContext.Provider value={contextValue}>{children}</DrawerMenuStateContext.Provider>
233	            </LeftBar>
234	            <RightBar
235	              hasBasket={!!basket}
236	              totalItems={totalItems}
237	              isRegistered={isRegistered}
238	              filteredNavLinks={filteredNavLinks}
239	              showLaunchAgentButton={showLaunchAgentButton}
240	              storeLocatorEnabled={storeLocatorEnabled}
241	              searchInputRef={searchInputRef}
242	              onMyAccountClick={onMyAccountClick}
243	              onMyCartClick={onMyCartClick}
244	              onWishlistClick={onWishlistClick}
245	              onAgentClick={onAgentClick}
246	              onStoreLocatorClick={onStoreLocatorClick}
247	              onSignout={onSignout}
248	              menuExpanded={menuExpanded}
249	              onClose={onCloseMenu}
250	            />
251	          </chakra.div>
252	
253	          {/* ── Row 2: logo only — hidden while the mobile drawer is open. Figma's mobile
254	              "Navigation" component drops to a 72px Exit/search/bag row with no wordmark. */}
255	          {/* display:flex lives in header.ts's logoBar recipe — no inline prop needed. */}
256	          {mobileMenuExpanded === 'closed' && (
257	            <chakra.div __css={styles.logoBar}>
258	              <Button
259	                aria-label={t('header.button.assistive_msg.logo', 'Logo')}
260	                variant="unstyled"
261	                onClick={onLogoClick}
262	                __css={styles.logoButton}
263	              >
264	                {/* SFCC-747: real wordmark, sized via HEADER_LOGO_SX above — previously rendered
265	                    the base template's placeholder BrandLogo icon. `sx`, not `style`: a plain
266	                    DOM style attribute can't express Chakra's responsive breakpoint values. */}
267	                <ZimmLogo sx={HEADER_LOGO_SX} />
268	              </Button>
269	            </chakra.div>
270	          )}
271	
272	          {/* Mobile-only search — commented out, pending searchPopover implementation */}
273	          {/* <HideOnDesktop display={{ base: 'block', lg: 'none' }}><SearchBar /></HideOnDesktop> */}
274	        </chakra.div>
275	      </chakra.header>
276	    </MegaMenuOpenContext.Provider>
277	  );
278	};
279	
280	export default Header;
