30	 * @param props see ListMenuViewProps
31	 */
32	export const ListMenuView = ({ items, isLoading, maxColumns = MAXIMUM_NUMBER_COLUMNS }: ListMenuViewProps) => {
33	  // components.ListMenu is dynamically registered and has no static type — cast unavoidable.
34	  const { components } = useTheme() as {
35	    components: Record<string, { baseStyle: Record<string, Record<string, unknown>> }>;
